//! Differential test against the Python terminal emulator (`i14ui/vt.py`):
//! generated byte streams full of escape sequences, split at random points and
//! mixed with resizes, go through both; the complete emulator state must match.
//! Needs `python3`. I14_VT_CASES sets the number of cases (default 400).

use std::io::Write;
use std::path::PathBuf;
use std::process::{Command, Stdio};

use i14_ui::vt::{Attr, Color, State, Vt};
use serde_json::{json, Value};

struct Rng(u64);

impl Rng {
    fn next(&mut self) -> u64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        self.0
    }
    fn below(&mut self, n: usize) -> usize {
        (self.next() % n as u64) as usize
    }
    fn pick<'a, T>(&mut self, items: &'a [T]) -> &'a T {
        &items[self.below(items.len())]
    }
}

fn token(r: &mut Rng, out: &mut Vec<u8>) {
    const NUMS: &[&str] = &[
        "",
        "0",
        "1",
        "2",
        "3",
        "4",
        "5",
        "6",
        "7",
        "8",
        "25",
        "38",
        "48",
        "47",
        "1047",
        "1049",
        "255",
        "256",
        "99999999999999999999",
        "12:3",
    ];
    const FINALS: &[u8] = b"ABCDEFGHJKLMPSTXdefghlmnrsucgb@`a";
    match r.below(20) {
        0..=5 => out.push(*r.pick(b"abcdefghijklmnopqrstuvwxyz ABC0123456789~`{|}")),
        6 => out.extend_from_slice(r.pick(&[
            "é".as_bytes(),
            "─".as_bytes(),
            "😀".as_bytes(),
            b"\xff",
            b"\xc3",
            b"\x80",
            b"\xed\xa0\x80",
        ])),
        7 | 8 => out.push(*r.pick(b"\r\n\t\x08\x0b\x0c\x07\x00\x7f")),
        9..=14 => {
            out.extend_from_slice(b"\x1b[");
            out.extend_from_slice(r.pick(&["", "", "", "?", ">", "!", "="]).as_bytes());
            let n = r.below(6);
            for i in 0..n {
                if i > 0 {
                    out.push(b';');
                }
                out.extend_from_slice(r.pick(NUMS).as_bytes());
            }
            if r.below(30) == 0 {
                out.push(b'\n'); // C0 inside a sequence
            }
            out.push(*r.pick(FINALS));
        }
        15 => {
            out.push(0x1b);
            out.push(*r.pick(b"78DEMHc()*+#]P[X^_"));
            out.push(*r.pick(b"0B8a\\q"));
        }
        16 => out.extend_from_slice(r.pick(&[
            &b"\x1b]0;title\x07"[..],
            b"\x1b]2;x\x1b\\",
            b"\x1b#8",
            b"\x1b(0lqqk\x1b(B",
        ])),
        17 => out.extend_from_slice(b"\x1b[38;2;1;2;3m\x1b[48;5;300m\x1b[38;5;9mX\x1b[0m"),
        18 => {
            let n = r.below(80);
            out.extend((0..n).map(|i| b'a' + (i % 26) as u8));
        }
        _ => out.extend_from_slice(r.pick(&[
            &b"\x1b[2;4r"[..],
            b"\x1b[r",
            b"\x1b[?6h",
            b"\x1b[?6l",
            b"\x1b[4h",
            b"\x1b[?1049h",
            b"\x1b[?1049l",
            b"\x1b[3J",
        ])),
    }
}

fn case(seed: u64) -> Value {
    let mut r = Rng(seed.wrapping_mul(2654435761).wrapping_add(1));
    let (cols, rows, sb) = (1 + r.below(20), 1 + r.below(9), *r.pick(&[0usize, 3, 50]));
    let mut ops = Vec::new();
    for _ in 0..(5 + r.below(40)) {
        if r.below(12) == 0 {
            ops.push(json!(["resize", 1 + r.below(20), 1 + r.below(9)]));
        } else {
            let mut bytes = Vec::new();
            for _ in 0..(1 + r.below(12)) {
                token(&mut r, &mut bytes);
            }
            // split anywhere, also inside UTF-8 and escape sequences
            let cut = r.below(bytes.len() + 1);
            ops.push(json!(["feed", hex(&bytes[..cut])]));
            ops.push(json!(["feed", hex(&bytes[cut..])]));
        }
    }
    json!({"cols": cols, "rows": rows, "sb": sb, "ops": ops})
}

fn hex(b: &[u8]) -> String {
    b.iter().map(|x| format!("{x:02x}")).collect()
}

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

fn color(c: Option<Color>) -> Value {
    match c {
        None => Value::Null,
        Some(Color::Index(i)) => json!(i),
        Some(Color::Rgb(r, g, b)) => json!([r, g, b]),
    }
}

fn attr(a: Attr) -> Value {
    json!([color(a.fg), color(a.bg), a.flags])
}

fn lines<'a>(ls: impl IntoIterator<Item = &'a Vec<i14_ui::vt::Cell>>) -> Value {
    ls.into_iter()
        .map(|l| {
            l.iter()
                .map(|c| json!([c.ch.to_string(), attr(c.attr)]))
                .collect::<Vec<_>>()
        })
        .collect()
}

const KEYS: &[(&str, bool, bool)] = &[
    ("up", false, false),
    ("home", false, true),
    ("c", true, false),
    ("[", true, true),
    (" ", true, false),
    ("x", false, false),
    ("pgdn", false, false),
];

fn dump(v: &Vt, replies: &[u8]) -> Value {
    let state = match v.state {
        State::Ground => "ground",
        State::Esc => "esc",
        State::Csi => "csi",
        State::String => "string",
        State::StringEsc => "string_esc",
        State::Charset0 => "charset0",
        State::Charset1 => "charset1",
        State::Hash => "hash",
    };
    json!({
        "cols": v.cols, "rows": v.rows, "main": lines(&v.main), "alt": v.alt.as_ref().map(lines),
        "scrollback": lines(&v.scrollback), "x": v.x, "y": v.y, "attr": attr(v.attr),
        "wrap": v.wrap_pending, "top": v.top, "bottom": v.bottom, "autowrap": v.autowrap,
        "origin": v.origin, "insert": v.insert, "app_cursor": v.app_cursor, "cursor": v.cursor_visible,
        "saved": [v.saved.x, v.saved.y, attr(v.saved.attr), v.saved.g0_graphics], "g0": v.g0_graphics,
        "tabs": v.tabs.iter().copied().collect::<Vec<_>>(), "state": state, "params": v.params,
        "replies": hex(replies), "text": v.text(), "view": lines(v.view(2)),
        "keys": KEYS.iter().map(|(k, c, a)| hex(&v.key_bytes(k, *c, *a))).collect::<Vec<_>>(),
    })
}

const PY: &str = r#"
import json, sys
from i14ui import vt
KEYS = json.loads(sys.argv[1])
def color(c):
    return list(c) if isinstance(c, tuple) else c
def attr(a):
    return [color(a[0]), color(a[1]), a[2]]
def lines(ls):
    return [[[c[0], attr(c[1])] for c in l] for l in ls]
out = []
for case in json.load(sys.stdin):
    replies = bytearray()
    v = vt.VT(case["cols"], case["rows"], reply=replies.extend, scrollback=case["sb"])
    for op in case["ops"]:
        if op[0] == "feed":
            v.feed(bytes.fromhex(op[1]))
        else:
            v.resize(op[1], op[2])
    out.append({
        "cols": v.cols, "rows": v.rows, "main": lines(v.main), "alt": None if v.alt is None else lines(v.alt),
        "scrollback": lines(v.scrollback), "x": v.x, "y": v.y, "attr": attr(v.attr),
        "wrap": v.wrap_pending, "top": v.top, "bottom": v.bottom, "autowrap": v.autowrap,
        "origin": v.origin, "insert": v.insert, "app_cursor": v.app_cursor, "cursor": v.cursor_visible,
        "saved": [v.saved[0], v.saved[1], attr(v.saved[2]), v.saved[3]], "g0": v.g0_graphics,
        "tabs": sorted(v.tabs), "state": v.state, "params": v.params,
        "replies": replies.hex(), "text": v.text(), "view": lines(v.view(2)),
        "keys": [v.key_bytes(k, c, a).hex() for k, c, a in KEYS],
    })
json.dump(out, sys.stdout)
"#;

#[test]
fn vt_matches_python() {
    let n: u64 = std::env::var("I14_VT_CASES")
        .ok()
        .and_then(|s| s.parse().ok())
        .unwrap_or(400);
    let cases: Vec<Value> = (0..n).map(case).collect();
    let lib = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../../rootfs/overlay/usr/lib");
    let mut child = Command::new("python3")
        .arg("-c")
        .arg(PY)
        .arg(
            serde_json::to_string(
                &KEYS
                    .iter()
                    .map(|(k, c, a)| json!([k, c, a]))
                    .collect::<Vec<_>>(),
            )
            .unwrap(),
        )
        .env("PYTHONPATH", lib)
        .env("PYTHONDONTWRITEBYTECODE", "1")
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .expect("python3");
    let input = serde_json::to_vec(&cases).unwrap();
    let mut stdin = child.stdin.take().unwrap();
    let writer = std::thread::spawn(move || stdin.write_all(&input));
    let out = child.wait_with_output().unwrap();
    writer.join().unwrap().unwrap();
    assert!(out.status.success());
    let expected: Vec<Value> = serde_json::from_slice(&out.stdout).unwrap();

    for (i, (c, want)) in cases.iter().zip(&expected).enumerate() {
        let mut v = Vt::new(
            c["cols"].as_u64().unwrap() as usize,
            c["rows"].as_u64().unwrap() as usize,
            c["sb"].as_u64().unwrap() as usize,
        );
        for op in c["ops"].as_array().unwrap() {
            if op[0] == "feed" {
                v.feed(&unhex(op[1].as_str().unwrap()));
            } else {
                v.resize(
                    op[1].as_u64().unwrap() as usize,
                    op[2].as_u64().unwrap() as usize,
                );
            }
        }
        let replies = std::mem::take(&mut v.replies);
        let got = dump(&v, &replies);
        if &got != want {
            let keys: Vec<_> = want
                .as_object()
                .unwrap()
                .keys()
                .filter(|k| got[k.as_str()] != want[k.as_str()])
                .collect();
            panic!(
                "case {i} differs in {keys:?}\ncase: {c}\nwant text: {}\ngot text: {}",
                want["text"], got["text"]
            );
        }
    }
}
